     "平均フィルタ、ガウシアンフィルタ、微分フィルタは、いずれもLSI系です。一方、メディアンフィルタ、形態学演算、バイラテラルフィルタ、適応的閾値処理は非線形系です。これらは、どちらかの性質を満たしません。そのため、扱いの理論が異なります。"
