     "このモデルは、2種類のパラメータで記述されます。内部パラメータは、焦点距離・主点・画素の縦横比です。外部パラメータは、カメラの位置と姿勢です。カメラキャリブレーションは、これらを推定する手続きです。内部パラメータと、後述する歪みを、既知のパターンから推定します。"
