     "歪みは、見た目だけの問題ではありません。まっすぐなものが曲がって写るだけではなく、位置測定の系統誤差になります。定量的に扱うには、前提となる手順があります。キャリブレーションで係数を推定し、補正（歪み除去）してから測定します。"
